<?php require_once __DIR__.'/../includes/security.php';require __DIR__.'/../includes/db.php';require_admin();require __DIR__.'/_layout.php';$today=$pdo->query("SELECT COUNT(*) n,COALESCE(SUM(total),0) revenue FROM orders WHERE DATE(created_at)=CURDATE()")->fetch();$all=$pdo->query("SELECT COUNT(*) n,COALESCE(SUM(total),0) revenue FROM orders")->fetch();$pending=$pdo->query("SELECT COUNT(*) FROM orders WHERE status='Menunggu pembayaran'")->fetchColumn();$customers=$pdo->query('SELECT COUNT(DISTINCT email) FROM orders')->fetchColumn();$recent=$pdo->query('SELECT id,order_number,customer_name,email,total,status,created_at FROM orders ORDER BY id DESC LIMIT 8')->fetchAll();admin_header('Ringkasan');?><main class="adminmain"><div class="adminhead"><div><span class="eyebrow">PANEL TOKOKITA</span><h1>Ringkasan toko</h1></div><a class="btn" href="orders.php">Kelola pesanan →</a></div><section class="kpis"><div class="kpi"><span>Transaksi hari ini</span><strong><?=number_format($today['n'])?></strong></div><div class="kpi"><span>Omzet hari ini</span><strong style="font-size:20px"><?=rupiah($today['revenue'])?></strong></div><div class="kpi"><span>Menunggu pembayaran</span><strong><?=number_format($pending)?></strong></div><div class="kpi"><span>Total pesanan / pelanggan</span><strong><?=number_format($all['n'])?> / <?=number_format($customers)?></strong></div></section><div class="adminhead"><h2 style="font-size:18px">Pesanan terbaru</h2><a href="orders.php">Lihat semua</a></div><div class="tablewrap"><table class="admintable"><thead><tr><th>No. pesanan</th><th>Pelanggan</th><th>Total</th><th>Status</th><th>Dibuat</th><th></th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><?=e($r['order_number'])?></td><td><?=e($r['customer_name'])?><br><small><?=e($r['email'])?></small></td><td><?=rupiah($r['total'])?></td><td><span class="status-pill"><?=e($r['status'])?></span></td><td><?=e($r['created_at'])?></td><td><a href="order.php?id=<?=$r['id']?>">Detail</a></td></tr><?php endforeach?><?php if(!$recent):?><tr><td colspan="6">Belum ada transaksi.</td></tr><?php endif?></tbody></table></div><p class="adminnote">Ringkasan omzet menghitung semua status pesanan; tinjau status sebelum rekonsiliasi keuangan.</p></main><?php admin_footer();?>